-- =====================================================================
-- Cuina Casa · 0003: dades nutricionals dels aliments
-- Executa aquest fitxer sencer a Supabase → SQL Editor → New query → Run
-- (cal haver executat abans 0001 i 0002)
--
-- Valors aproximats i orientatius (referència BEDCA/USDA). No és consell mèdic.
-- =====================================================================

create table if not exists public.foods (
  id            uuid primary key default gen_random_uuid(),
  -- null = aliment de referència compartit; si no, aliment propi d'una llar
  household_id  uuid references public.households(id) on delete cascade,
  name          text not null check (char_length(name) between 1 and 120),
  aliases       text[] not null default '{}',
  -- valors per 100 g
  kcal          numeric not null default 0 check (kcal >= 0),
  carbs         numeric not null default 0 check (carbs >= 0),
  protein       numeric not null default 0 check (protein >= 0),
  fat           numeric not null default 0 check (fat >= 0),
  fiber         numeric not null default 0 check (fiber >= 0),
  harvard_group text not null default 'condiment' check (harvard_group in (
    'verdura', 'fruita', 'patata', 'cereal_integral', 'cereal_refinat', 'llegum', 'peix', 'ou',
    'aviram', 'carn_vermella', 'carn_processada', 'fruits_secs', 'lactic', 'oli', 'greix',
    'sucre', 'condiment', 'beguda'
  )),
  unit_g        numeric check (unit_g is null or unit_g > 0),   -- pes d'1 unitat (1 ceba, 1 ou…)
  pack_g        numeric check (pack_g is null or pack_g > 0),   -- pes d'1 llauna, pot o paquet
  density       numeric not null default 1 check (density > 0), -- g per ml
  plate_factor  numeric not null default 1 check (plate_factor > 0), -- l'arròs, la pasta… s'inflen en coure's
  barcode       text,
  source        text not null default 'referència' check (source in ('referència', 'manual', 'openfoodfacts')),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create unique index if not exists foods_reference_name_idx on public.foods (name) where household_id is null;
create unique index if not exists foods_household_name_idx on public.foods (household_id, name) where household_id is not null;
create index if not exists foods_household_idx on public.foods (household_id);

alter table public.foods enable row level security;

drop policy if exists "tothom veu aliments de referència i els de la seva llar" on public.foods;
create policy "tothom veu aliments de referència i els de la seva llar" on public.foods
  for select using (household_id is null or public.is_member(household_id));

drop policy if exists "membres gestionen aliments propis" on public.foods;
create policy "membres gestionen aliments propis" on public.foods
  for all
  using (household_id is not null and public.is_member(household_id))
  with check (household_id is not null and public.is_member(household_id));

drop trigger if exists foods_touch on public.foods;
create trigger foods_touch before update on public.foods
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------
-- Aliments de referència (generat amb scripts/generar-aliments.py)
-- ---------------------------------------------------------------------
on conflict (name) where household_id is null do update set
  aliases = excluded.aliases, kcal = excluded.kcal, carbs = excluded.carbs, protein = excluded.protein,
  fat = excluded.fat, fiber = excluded.fiber, harvard_group = excluded.harvard_group, unit_g = excluded.unit_g,
  pack_g = excluded.pack_g, density = excluded.density, plate_factor = excluded.plate_factor;
